from typing import Any


class CloudGnbPmcountersCollectorConfigurator:
    def add_pmcounters(self: Any, ne_log_name: str, ne_log_configuration: dict):

        cu_webservice = self.tl_config_information_provider.get_cu_oam_http_connection_details(node_id=self.ne_id)
        pmcounters_cu_collector_configuration = {
            'name': f"{ne_log_name}_cu",
            'type': "pmcounters",
            'oam_type': "coam_vcu",
            'webservice': cu_webservice
        }
        self._collector_configuration_data.append(pmcounters_cu_collector_configuration)
        pm_counter_collector_names = [pmcounters_cu_collector_configuration['name']]

        for vdu_id in self.tl_config_information_provider.get_du_ids(node_id=self.ne_id):
            vdu_webservice = self.tl_config_information_provider.get_vdu_oam_http_connection_details(node_id=self.ne_id, vdu_id=vdu_id)
            pmcounters_vdu_collector_configuration = {
                'name': f"{ne_log_name}_vdu_{vdu_id}",
                'type': "pmcounters",
                'oam_type': "coam_vdu",
                'webservice': vdu_webservice
            }
            self._collector_configuration_data.append(pmcounters_vdu_collector_configuration)
            pm_counter_collector_names.append(pmcounters_vdu_collector_configuration['name'])

        pm_counter_collector_config = {
            'type': 'group',
            'name': f"{ne_log_name}",
            'members': pm_counter_collector_names}

        self._collector_configuration_data.append(pm_counter_collector_config)
        self._collector_configuration_data.add_mapping_entry(
            log_type='pmcounter',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=pm_counter_collector_config)
